import{_ as n,c as a,o as s,ae as t}from"./chunks/framework.CFeneB-q.js";const S=JSON.parse('{"title":"PC 端 · SSO 登录链路","description":"","frontmatter":{},"headers":[],"relativePath":"pc/references/sso-login.md","filePath":"pc/references/sso-login.md","lastUpdated":1789438865000}'),o={name:"pc/references/sso-login.md"};function p(c,e,d,l,i,r){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="pc-端-·-sso-登录链路" tabindex="-1">PC 端 · SSO 登录链路 <a class="header-anchor" href="#pc-端-·-sso-登录链路" aria-label="Permalink to &quot;PC 端 · SSO 登录链路&quot;">​</a></h1><blockquote><p>基于 <code>keystone-deliver-ui/src/permission.js</code>（路由守卫，2026-09-16 核对）。SSO 平台为 e9-sso-ui。</p></blockquote><h2 id="登录时序" tabindex="-1">登录时序 <a class="header-anchor" href="#登录时序" aria-label="Permalink to &quot;登录时序&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户访问页面</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ URL 带 SSO 回跳参数（token, accountId, isSync, tokenType, language…）</span></span>
<span class="line"><span>  │    └─ 落缓存（token / accountId / tenantId / timezone / header 等）</span></span>
<span class="line"><span>  │       → 语言归一（zh/en/es）→ i18next.changeLanguage</span></span>
<span class="line"><span>  │       → 校验第三方账户（accountThirdExistApi）</span></span>
<span class="line"><span>  │       → window.location.href = origin（清参回跳，重新进入守卫）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 无 token 且不在白名单</span></span>
<span class="line"><span>  │    └─ getSSOAddressApi() 取 SSO 地址</span></span>
<span class="line"><span>  │       （location 模式且 VITE_APP_USE_SSO=true → 用 VITE_APP_SSO_URL）</span></span>
<span class="line"><span>  │       → 跳 \`\${addressUrl}/#/login?fromSite=\${origin}&amp;redirect=\${encodeURIComponent(to.fullPath)}\`</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ 有 token</span></span>
<span class="line"><span>       ├─ 已有动态路由 → 校验目标路由有效性（findPathData，components 缺失跳 404）</span></span>
<span class="line"><span>       └─ 无动态路由 → personalInfo() → permissionStore.getCollectRouter()</span></span>
<span class="line"><span>            → getPermissionRoutes(groupId)（服务端菜单 → filterPermissionsRouters 转路由）</span></span>
<span class="line"><span>            → 逐条 router.addRoute() + 兜底 404 → next({ ...to, replace: true })</span></span></code></pre></div><h2 id="关键规则" tabindex="-1">关键规则 <a class="header-anchor" href="#关键规则" aria-label="Permalink to &quot;关键规则&quot;">​</a></h2><ul><li><strong>白名单</strong>：<code>WHITE_LIST = [&#39;Login&#39;]</code>（按 route name 匹配），仅登录页免登录可达；默认 <code>Token-Type: &#39;PC&#39;</code>；</li><li><strong>SSO 参数凭证变化</strong>：URL 带 SSO 参数且 <code>tokenChanged</code> 时强制走 SSO 处理，覆盖本地旧 token；</li><li><strong>SHARE 分享模式</strong>：<code>tokenType === &#39;SHARE&#39;</code> 走独立分支——错误页直通，按路由分组（<code>getRouteGroups</code>）拉路由，失败降级放行；</li><li><strong>多项目控制台</strong>：用户有多个路由分组时 <code>/</code> 与 <code>/dashboard</code> 重定向到 <code>/contorl-station</code>（控制台选项目）；单分组自动 <code>setGroupId</code> 并直进首屏；<code>_loadingRoutes</code> 防止并发重入；</li><li><strong>动态路由来源</strong>：服务端菜单的 <code>localFilePath</code> 字段映射到 <code>views/</code> 下组件——菜单配置错误（路径不存在）表现为 404 / 「当前角色无路由权限」。</li></ul><h2 id="常见排查" tabindex="-1">常见排查 <a class="header-anchor" href="#常见排查" aria-label="Permalink to &quot;常见排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>检查点</th></tr></thead><tbody><tr><td>无限跳 SSO</td><td>SSO 侧账号/凭证未生效；本地 <code>.env.location</code> 的 <code>VITE_APP_USE_SSO</code> 与 <code>VITE_APP_SSO_URL</code> 配置矛盾</td></tr><tr><td>登录后空白 / 404</td><td>菜单元数据的 <code>localFilePath</code> 与实际组件路径不一致</td></tr><tr><td>切语言后词条缺失</td><td>页面级 <code>locale/*.json</code> 未建或 key 与中文原文不一致（跑 <code>pnpm i18n:verify-keys</code>）</td></tr><tr><td>401 后直接跳走无提示</td><td>标品行为如此（无弹窗），见<a href="./http-request.html#401-302-处理">请求封装参考</a></td></tr></tbody></table>`,8)])])}const u=n(o,[["render",p]]);export{S as __pageData,u as default};
